function repeatCombo(){const c=getCombo(activeCombo);if(!c)return;snapshot();state.cells=window.jaliPatterns.stamp(state.cells,window.jaliPatterns.rotate(c.grid,angle),0,0,true);state.preset='';render();toast('Combo repeated; edge motifs may be partial')}
$('#repeatCombo').onclick=repeatCombo;document.querySelectorAll('[data-combo-filter]').forEach(b=>b.onclick=()=>{comboFilter=b.dataset.comboFilter;document.querySelectorAll('[data-combo-filter]').forEach(el=>el.classList.toggle('active',el===b));buildCombos()});
$('#singleTab').onclick=()=>{$('#singleLibrary').hidden=false;$('#comboLibrary').hidden=true;$('#singleTab').classList.add('active');$('#comboTab').classList.remove('active');activeCombo=null;buildLibrary();setTool('paint');switchView('2d')};
$('#comboTab').onclick=()=>{$('#singleLibrary').hidden=true;$('#comboLibrary').hidden=false;$('#singleTab').classList.remove('active');$('#comboTab').classList.add('active');buildCombos()};
$('#captureCombo').onclick=()=>{if(!selection){toast('Select the top-left cell of your patch first');return}const R=+$('#captureRows').value,C=+$('#captureCols').value;if(selection.r+R>state.cells.length||selection.c+C>state.cells[0].length){toast('The patch extends beyond the wall');return}if((state.combos||[]).length>=30){toast('You can save up to 30 custom combos');return}const name=$('#comboName').value.trim()||'My '+C+' × '+R+' combo',grid=state.cells.slice(selection.r,selection.r+R).map(row=>row.slice(selection.c,selection.c+C).map(c=>c?{...c}:null));snapshot();const id='custom_'+crypto.randomUUID();state.combos=[...(state.combos||[]),{id,name,grid}];activeCombo=id;angle=0;$('#angle').textContent='0°';render();toast('Combo saved with your design')};
function updateBrushHUD(){$('#hudFillSelection').disabled=!selection;const combo=getCombo(activeCombo);$('#brushName').textContent=combo?combo.name:types.find(t=>t[0]===brush)?.[1]||'Petal';$('#brushRotation').textContent=angle+'°';$('#brushKind').textContent=combo?combo.grid[0].length+' × '+combo.grid.length+' combo':'Single block';$('#brushHUD').classList.toggle('combo-brush',!!combo)}
function showBrushGhost(r,c){$('#brushGhost')?.remove();if(tool!=='paint')return;const svg=$('#drawing svg');if(!svg)return;const grid=activeCombo?window.jaliPatterns.rotate(getCombo(activeCombo).grid,angle):[[{type:brush,rotation:angle}]],H=grid.length,W=grid[0].length,pitch=100+state.joint/(state.blockSize*25.4)*100,group=document.createElementNS('http://www.w3.org/2000/svg','g');group.id='brushGhost';group.setAttribute('pointer-events','none');const fits=r+H<=state.cells.length&&c+W<=state.cells[0].length;group.innerHTML=grid.map((row,dr)=>row.map((v,dc)=>v?`<g opacity=".5" transform="translate(${(c+dc)*pitch} ${(r+dr)*pitch})">${tileSVG(v.type,v.rotation)}</g>`:'').join('')).join('')+`<rect x="${c*pitch}" y="${r*pitch}" width="${W*pitch-(pitch-100)}" height="${H*pitch-(pitch-100)}" fill="none" stroke="${fits?'#315a3d':'#c34132'}" stroke-width="5"/>`;svg.appendChild(group)}
$('#hudRotateLeft').onclick=()=>{angle=(angle+270)%360;$('#angle').textContent=angle+'°';buildCombos();updateBrushHUD()};$('#hudRotateRight').onclick=()=>$('#rotateBrush').click();$('#hudFillSelection').onclick=()=>fillSelection();
function applyElevationScale(){const svg=$('#drawing svg');if(svg){svg.style.width=elevationScale*100+'%';svg.style.maxHeight=elevationScale>1?'none':'';svg.style.flexShrink='0'}$('#zoomLevel').textContent=elevationScale.toFixed(1).replace('.0','')+'×';$('#zoomOut').disabled=elevationScale<=1;$('#zoomIn').disabled=elevationScale>=4;$('#drawing').classList.toggle('zoomed',elevationScale>1)}
$('#zoomIn').onclick=()=>{elevationScale=Math.min(4,elevationScale+.5);applyElevationScale()};$('#zoomOut').onclick=()=>{elevationScale=Math.max(1,elevationScale-.5);applyElevationScale()};$('#zoomReset').onclick=()=>{elevationScale=1;$('#drawing').scrollTop=$('#drawing').scrollLeft=0;applyElevationScale()};
window.jali={cellSVG:tileSVG,setTool,clearSelection(){selection=regionSelection=multiSelection=null;updateSelection();window.dispatchEvent(new CustomEvent('jali-select'))},loadDesign(data){if(!valid(data))throw Error('The design is invalid or uses unsupported blocks');this.transaction(()=>{state=JSON.parse(JSON.stringify(data));selection=regionSelection=multiSelection=null});return this.state},validateDesign:valid,selectCell,setSelection,get selectedCells(){return selectionPoints()},get selectionBounds(){return selectedBounds()},fillSelection,get region(){return regionSelection},get brush(){return {id:activeCombo||brush,name:activeCombo?getCombo(activeCombo)?.name:types.find(t=>t[0]===brush)?.[1],rotation:angle,isCombo:!!activeCombo}},get combos(){return [...window.jaliPatterns.combos,...(state.combos||[])]},get rhythms(){return presetNames.map(([id,name])=>({id,name}))},applyRhythm:preset,get catalog(){return catalog},get types(){return types},get outlines(){return outlines},resize,history(direction){direction==='redo'?redo():undo()},transaction(fn){const before=JSON.stringify(state),prevH=undoHistory.slice(),prevF=future.slice();try{snapshot();fn(state);state.preset='';if(!valid(state))throw Error('Design edit is invalid');syncInputs();buildLibrary();render()}catch(e){state=JSON.parse(before);undoHistory=prevH;future=prevF;syncInputs();buildLibrary();render();throw e}},get view(){return currentView},get state(){return state},get holes(){return holes},get tool(){return tool},get selection(){return selection},pick(r,c){if(tool==='pan')return;if(tool==='select')selectCell(r,c);else{if(!(activeCombo&&tool==='paint'))snapshot();dragVisited.clear();editCell({closest:()=>({dataset:{row:r,col:c}})})}},rotate:rotateSelection};
